# -*- coding: utf-8 -*-
from gen2 import *

m1 = M(('Зеркальное отражение', 'A mirror image'),
 [('r', 'x', 'Расстояние вершины D до оси', 'Distance of vertex D from the axis', 10, 200, 5, 90), ('r', 'y', 'Высота вершины D', 'Height of vertex D', 20, 170, 5, 60)],
 [('D до оси', 'D to the axis'), ('D′ до оси', 'D′ to the axis'), ('Отрезок DD′', 'Segment DD′')],
 'Пунктир — ось симметрии. Каждая точка и её отражение лежат на одном перпендикуляре к оси на одинаковом расстоянии от неё.', 'The dashed line is the axis of symmetry. Every point and its image lie on one perpendicular to the axis at equal distances from it.', ('Фигура и её зеркальное отражение', 'A figure and its mirror image'),
 r'''const x=v.x,y=v.y,P=[[300+30,200],[300+130,200],[300+130,120],[300+x,y+20]],Q=P.map(p=>[600-p[0],p[1]]);
 let g=L(300,10,300,240,COL.mut,2)+poly(P,"#f4dfd8",COL.a,3)+poly(Q,"#dbe5f2",COL.b,3)+L(300+x,y+20,300-x,y+20,COL.ink,1.5)+C(300+x,y+20,6,COL.a)+C(300-x,y+20,6,COL.b)+TX(300+x+10,y+14,"D",COL.a,16,"start",600)+TX(300-x-10,y+14,"D′",COL.b,16,"end",600);
 return {svg:g,st:[x,x,2*x],fb:U("D и D′ одинаково удалены от оси: по "+x+", всего между ними "+2*x+".","D and D′ are equally far from the axis: "+x+" each, "+2*x+" apart.")}''')

m2 = M(('Оси симметрии', 'Axes of symmetry'),
 [('s', 'n', 'Фигура', 'Figure', ['равносторонний треугольник', 'квадрат', 'правильный пятиугольник', 'правильный шестиугольник', 'правильный восьмиугольник', 'круг'], ['equilateral triangle', 'square', 'regular pentagon', 'regular hexagon', 'regular octagon', 'circle'], 1)],
 [('Осей симметрии', 'Axes of symmetry'), ('Наименьший поворот, совмещающий фигуру с собой', 'Smallest turn that maps the figure onto itself'), ('Название', 'Name')],
 'У правильного n-угольника ровно n осей: через каждую вершину проходит ось. У круга их бесконечно много.', 'A regular n-gon has exactly n axes: an axis passes through every vertex. A circle has infinitely many.', ('Фигура с осями симметрии', 'A figure with axes of symmetry'),
 r'''const ns=[3,4,5,6,8,0],n=ns[v.n],cx=300,cy=125,R_=92;let g="";
 if(n===0){g+=C(cx,cy,R_,"#f4dfd8",COL.ink,3);for(let i=0;i<12;i++){const a=i*Math.PI/12;g+=L(cx+(R_+14)*Math.cos(a),cy-(R_+14)*Math.sin(a),cx-(R_+14)*Math.cos(a),cy+(R_+14)*Math.sin(a),COL.b,1.2)}}
 else{const P=[];for(let i=0;i<n;i++){const a=Math.PI/2+i*2*Math.PI/n;P.push([cx+R_*Math.cos(a),cy-R_*Math.sin(a)])}g+=poly(P,"#f4dfd8",COL.ink,3);for(let k=0;k<n;k++){const a=Math.PI/2+k*Math.PI/n;g+=L(cx+(R_+14)*Math.cos(a),cy-(R_+14)*Math.sin(a),cx-(R_+14)*Math.cos(a),cy+(R_+14)*Math.sin(a),COL.b,2)}}
 const nm=U(["равносторонний треугольник","квадрат","правильный пятиугольник","правильный шестиугольник","правильный восьмиугольник","круг"],["equilateral triangle","square","regular pentagon","regular hexagon","regular octagon","circle"])[v.n];
 return {svg:g,st:[n?n:"∞",n?fnum(360/n,1)+"°":U("любой угол","any angle"),nm],fb:n?(n%2?U("Каждая из "+n+" осей проходит через вершину и середину противоположной стороны.","Each of the "+n+" axes passes through a vertex and the midpoint of the opposite side."):U(n/2+" оси идут через противоположные вершины и "+n/2+" — через середины противоположных сторон: всего "+n+".",n/2+" axes go through opposite vertices and "+n/2+" through midpoints of opposite sides: "+n+" in all.")):U("У круга любая прямая через центр — ось симметрии.","For a circle every line through the centre is an axis of symmetry.")}''')

m3 = M(('Узор с поворотами', 'A rotational pattern'),
 [('r', 'k', 'Сколько лепестков', 'How many petals', 2, 12, 1, 8), ('r', 'w', 'Ширина лепестка', 'Petal width', 10, 70, 5, 35), ('r', 'l', 'Длина лепестка', 'Petal length', 40, 110, 5, 85)],
 [('Лепестков (поворотов)', 'Petals (turns)'), ('Угол между лепестками', 'Angle between petals'), ('Осей симметрии', 'Axes of symmetry')],
 'Лепесток повторяется поворотом вокруг центра. Так устроены многие узоры на коврах и в орнаментах.', 'A petal is repeated by turning about the centre. Many carpet patterns and ornaments are built this way.', ('Розетка: лепесток повернут несколько раз', 'A rosette: one petal turned several times'),
 r'''const k=v.k;let g="";for(let i=0;i<k;i++){const a=i*360/k;g+='<ellipse cx="300" cy="'+(125-v.l/2)+'" rx="'+v.w/2+'" ry="'+v.l/2+'" fill="'+(i%2?"#dbe5f2":"#f4dfd8")+'" stroke="'+(i%2?COL.b:COL.a)+'" stroke-width="2" transform="rotate('+a+' 300 125)"/>'}
 g+=C(300,125,5,COL.ink);return {svg:g,st:[k,fnum(360/k,1)+"°",k],fb:U("Поворот на "+fnum(360/k,1)+"° переводит узор в себя; осей симметрии "+k+".","A turn by "+fnum(360/k,1)+"° maps the pattern onto itself; there are "+k+" axes of symmetry.")}''')

chapter('12', '12-symmetry.html', 'II', ('Симметрия и орнамент', 'Symmetry and ornament'),
 ('Сколько осей симметрии у квадрата и у круга и как из одного лепестка получается узор.', 'How many axes of symmetry a square and a circle have, and how one petal makes a pattern.'),
 ('Мастерица рассматривает узоры на ковре: у одного есть оси симметрии, у другого их нет.\n\nСколько осей симметрии у квадрата, у прямоугольника (не квадрата) и у круга?', 'A craftswoman looks at the patterns on a carpet: one has axes of symmetry, another has none.\n\nHow many axes of symmetry do a square, a rectangle (not a square) and a circle have?'),
 ('Разгадка: 4, 2 и бесконечно много', 'The answer: 4, 2 and infinitely many'),
 ('Квадрат складывается пополам вдоль 4 прямых: двух диагоналей и двух прямых через середины противоположных сторон — осей 4. У прямоугольника, не квадрата, диагонали не годятся: остаются две прямые через середины сторон — осей 2. Круг совмещается с собой при отражении относительно любого диаметра — осей бесконечно много.', 'A square folds in half along 4 lines: the two diagonals and the two lines through the midpoints of opposite sides — 4 axes. For a rectangle that is not a square the diagonals do not work: two lines through the midpoints of the sides remain — 2 axes. A circle maps onto itself under reflection in any diameter — infinitely many axes.'),
 [S('mirror', 'Осевая симметрия', 'Mirror symmetry', ('Фигура <strong>симметрична</strong> относительно прямой (оси), если при сгибании по оси две половины совпадают. Две точки <strong>симметричны</strong> относительно оси, если ось — серединный перпендикуляр к отрезку между ними: расстояния до оси равны.', 'A figure is <strong>symmetric</strong> about a line (the axis) if the two halves coincide when folded along the axis. Two points are <strong>symmetric</strong> about an axis if the axis is the perpendicular bisector of the segment between them: their distances from the axis are equal.'),
    ('DD′ ⊥ ось', 'расстояния от D и D′ до оси равны', 'the distances from D and D′ to the axis are equal'), m1),
  S('axes', 'Оси симметрии фигур', 'Axes of symmetry of figures', ('У равностороннего треугольника 3 оси, у квадрата — 4, у правильного n-угольника — ровно n. У круга осей бесконечно много. Есть и фигуры без осей — например, неравносторонний неправильный четырёхугольник общего вида.', 'An equilateral triangle has 3 axes, a square 4, a regular n-gon exactly n. A circle has infinitely many. Some figures have none — for example a general irregular quadrilateral.'),
    ('n-угольник: n осей', 'поворот на 360°/n совмещает его с собой', 'n-gon: n axes; a turn by 360°/n maps it onto itself'), m2),
  S('orn', 'Орнамент и поворот', 'Ornament and rotation', ('Орнамент строят из одного мотива, который повторяют сдвигами, отражениями или поворотами. Если мотив повторён <em>k</em> раз с поворотом на 360°/k, получается розетка с <em>k</em> осями симметрии. Такие узоры часто встречаются на коврах и войлочных изделиях.', 'An ornament is built from one motif repeated by shifts, reflections or turns. If a motif is repeated <em>k</em> times with a turn of 360°/k, we get a rosette with <em>k</em> axes of symmetry. Such patterns are common on carpets and felt crafts.'),
    ('угол поворота = 360° : k', 'k = 8 → 45°', 'k = 8 → 45°'), m3)],
 [TK(('Отражённая точка', 'A reflected point'), ('Точка D удалена от оси симметрии на 7 см. На каком расстоянии от оси её отражение D′ и чему равен отрезок DD′?', 'Point D is 7 cm from the axis. How far from the axis is its image D′ and what is the length of DD′?'), 'DD = 7 см', 'Расстояние до оси то же: 7 см. DD′ = 7 + 7 = 14 см.', ('7 см и 14 см.', '7 cm and 14 cm.')),
  TK(('Оси прямоугольника', 'Axes of a rectangle'), ('Сколько осей симметрии у прямоугольника 3 × 5?', 'How many axes of symmetry has a 3 × 5 rectangle?'), '3 × 5', 'Две оси — прямые через середины противоположных сторон. Диагонали осями не являются.', ('2.', '2.')),
  TK(('Угол поворота', 'Angle of turn'), ('Розетка состоит из 6 одинаковых лепестков. На какой угол надо повернуть её, чтобы она совместилась с собой?', 'A rosette has 6 identical petals. By what angle must it be turned to coincide with itself?'), 'k = 6', '360° : 6 = 60°.', '60°.'),
  TK(('Сколько осей у розетки', 'Axes of a rosette'), ('Сколько осей симметрии у розетки с 12 одинаковыми лепестками?', 'How many axes of symmetry has a rosette with 12 identical petals?'), 'k = 12', 'Если лепесток сам симметричен, осей столько же, сколько лепестков.', '12.'),
  TK(('Дополни до симметрии', 'Complete the symmetry'), ('Вершина A стоит на 3 клетки левее оси. Где стоит симметричная ей вершина A′?', 'Vertex A stands 3 squares left of the axis. Where is its symmetric vertex A′?'), 'A: 3 клетки влево', 'Тоже на расстоянии 3 клетки, но по другую сторону — вправо. Между A и A′ — 6 клеток.', ('На 3 клетки правее оси.', '3 squares to the right of the axis.'))],
 [Q('Сколько осей симметрии у квадрата?', 'How many axes of symmetry has a square?', '4', '2', '8', ('Две диагонали и две средние линии.', 'Two diagonals and two midlines.')),
  Q('Сколько осей у круга?', 'How many axes has a circle?', ('Бесконечно много', 'Infinitely many'), ('1', '1'), ('4', '4'), ('Любой диаметр — ось.', 'Any diameter is an axis.')),
  Q('Что верно для симметричных точек?', 'What is true of two symmetric points?', ('Они одинаково удалены от оси', 'They are equally far from the axis'), ('Они совпадают', 'They coincide'), ('Они лежат на оси', 'They lie on the axis'), ('Ось — серединный перпендикуляр к их отрезку.', 'The axis is the perpendicular bisector of their segment.')),
  Q('Угол поворота розетки из 8 лепестков', 'The angle of turn of an 8-petal rosette', '45°', '8°', '90°', ('360° : 8 = 45°.', '360° : 8 = 45°.')),
  Q('Сколько осей у равностороннего треугольника?', 'How many axes has an equilateral triangle?', '3', '1', '6', ('По одной через каждую вершину.', 'One through each vertex.')),
  Q('Сколько осей у прямоугольника (не квадрата)?', 'How many axes has a rectangle that is not a square?', '2', '4', '1', ('Диагонали осями не служат.', 'The diagonals are not axes.')),
  Q('Что такое орнамент?', 'What is an ornament?', ('Повторяющийся мотив', 'A repeated motif'), ('Одна точка', 'A single point'), ('Длина отрезка', 'The length of a segment'), ('Узор строится из повторов мотива.', 'A pattern is built from repeats of a motif.')),
  Q('Точка в 5 см от оси. Расстояние между ней и отражением?', 'A point is 5 cm from the axis. The distance to its image?', '10 см', '5 см', '0 см', ('5 + 5 = 10.', '5 + 5 = 10.'))],
 src=[('Wikipedia: Symmetry', 'https://en.wikipedia.org/wiki/Symmetry'), ('Wikipedia: Rotational symmetry', 'https://en.wikipedia.org/wiki/Rotational_symmetry')])
